            8'b00010000: pos = 3'd4;
            8'b00001000: pos = 3'd3;
            8'b00000100: pos = 3'd2;
            8'b00000010: pos = 3'd1;
            8'b00000001: pos = 3'd0;
            default: begin
                valid = 1'b0;
                pos = 3'd0;
            end
        endcase
    end

endmodule

