module top_module(
    input [69:0] data,
    input rdclk,
    input rdreq,
    input wrclk,
    input wrreq,
    output reg [69:0] q, // Changed to reg
    output rdempty,
    output wrfull
);reg [69:0] fifo [0:255];
    reg [7:0] rdptr = 0;
    reg [7:0] wrptr = 0;
    reg [7:0] count = 0;
    wire full = (count == 256);
    wire empty = (count == 0);
    assign rdempty = empty;
    assign wrfull = full;

    always @(posedge wrclk) begin
        if (wrreq && !full) begin
            fifo[wrptr] <= data;
            wrptr <= (wrptr == 255) ? 0 : wrptr + 1;
            count <= count + 1;
        end
    end

    always @(posedge rdclk) begin
        if (rdreq && !empty) begin
            q <= fifo[rdptr]; // Now valid as q is a reg
            rdptr <= (rdptr == 255) ? 0 : rdptr + 1;
            count <= count - 1;
        end
    end

endmodule

