description:
Design a Verilog module for a 4-bit binary to BCD converter with synchronous active high reset.
// (1) reset: Resets the output to 4'b0000 when high.
// (2) bin: 4-bit binary input.
// (3) bcd: Binary Coded Decimal output.

module bin_to_bcd(
    input clk,
    input reset,
    input [3:0] bin,
    output reg [3:0] bcd);

code:
module bin_to_bcd(
    input clk,
    input reset,
    input [3:0] bin,
    output reg [3:0] bcd
);

    always @(posedge clk) begin
        if (reset) begin
            // Synchronous reset
            bcd <= 4'b0000;
        end else begin
            // Binary to BCD conversion logic
            bcd <= (bin >= 4'b1010) ? (bin + 4'b0110) : bin;
        end
    end

endmodule

