    input clk, rst,
    output reg [2:0] traffic_light
);

code:
module top_module(
    input clk, rst,
    output reg [2:0] traffic_light
);reg [3:0] count;

    always @(posedge clk or posedge rst)
        if(rst)
            count <= 0;
        else if(count == 20)
            count <= 0;
        else
            count <= count + 1;

    always @(posedge clk or posedge rst)
        if(rst)
            traffic_light <= 3'b100;
        else if(count < 10)
            traffic_light <= 3'b100; // red
        else if(count < 12)
            traffic_light <= 3'b010; // yellow
        else if(count < 22)
            traffic_light <= 3'b001; // green
        else
            traffic_light <= 3'b100; // red

endmodule

