code:
module top_module (
        input clk,
        input areset,
        input coin,
        input reset_dispense,
        output reg dispense);parameter Idle=2'b00, Accept=2'b01, Dispense=2'b10;
	reg [1:0] state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= Idle;
		else begin
			case (state)
				Idle: state <= coin ? Accept : Idle;
				Accept: state <= coin ? Accept : Dispense;
				Dispense: state <= reset_dispense ? Idle : Dispense;
			endcase
		end
	end

	assign dispense = (state == Dispense);

endmodule

